#include "plugins/limiter/Dsp.hpp"
#include <fstream>
using namespace just;using namespace just::limiter;
int main(int argc,char**argv){for(int m=0;m<2;m++){auto s=initialState({},registry);s.targets[mode]=m;s.targets[ceiling]=parameters[ceiling].toNormalized(-2.7);s.targets[input]=parameters[input].toNormalized(3.1);s.targets[trim]=parameters[trim].toNormalized(-1.3);s.targets[release]=parameters[release].toNormalized(87.3);s.targets[transient]=.88;s.targets[lookahead]=.86;s.targets[guide]=.68;auto bytes=encodeState(s,registry);auto name=std::string(argv[1])+"/legacy-"+std::to_string(m);std::ofstream(name+".state",std::ios::binary).write((char*)bytes.data(),bytes.size());LimiterEngine e;e.prepare({48000,1,2,2});e.applyTargets(s,0);std::ofstream audio(name+".f64",std::ios::binary);for(int i=0;i<2048;i++){double l=i<1400?(i%29==0?3.7:.67*std::sin(i*.13)):0,r=-.43*l,out[2];AudioBlock<double>b{{&l,&r},{out,out+1},2,2,1};e.process(b,{});audio.write((char*)out,sizeof(out));}}}
